implementation:
void calculate_tile_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno, OPJ_INT32 *p_tx0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty0, OPJ_INT32 *p_ty1, OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec, OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 compno;
    OPJ_UINT32 resno;
    OPJ_UINT32 dx, dy;
    OPJ_UINT32 max_dx = 0;
    OPJ_UINT32 max_dy = 0;
    OPJ_UINT32 max_precision = 0;

    if (!p_image || !p_cp || !p_tx0 || !p_tx1 || !p_ty0 || !p_ty1 || !p_dx_min || !p_dy_min || !p_max_prec || !p_max_res) {
        return;
    }

    *p_tx0 = 0;
    *p_tx1 = p_image->x1;
    *p_ty0 = 0;
    *p_ty1 = p_image->y1;

    for (compno = 0; compno < p_image->numcomps; ++compno) {
        const opj_tcp_t *tcp = &p_cp->tcp[compno];
        const opj_tccp_t *tccp = &tcp->tccps[0];

        for (resno = 0; resno < tccp->numresolution; ++resno) {
            dx = tccp->resolutions[resno].dx;
            dy = tccp->resolutions[resno].dy;

            if (dx > max_dx) {
                max_dx = dx;
            }
            if (dy > max_dy) {
                max_dy = dy;
            }

            if (resno + 1 > max_precision) {
                max_precision = resno + 1;
            }
        }
    }

    *p_dx_min = max_dx;
    *p_dy_min = max_dy;
    *p_max_prec = max_precision;
    *p_max_res = max_precision;
}
